using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public class MissionEntryTests
{
    static Intent Plan(ContractWorld w,long amount=27,int deadline=37,EntityId? executor=null)=>MissionEntry.Build(w,"request:custom",ActionKind.Transfer,executor??ContractFixture.Clerk,amount,deadline);
    [Fact] public void ChosenFieldsReachExistingTaskAndResourceLedger(){var s=new WorldSession(MissionEntry.Create());var i=Plan(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);s.AdvanceTo(12);var w=s.DiagnosticSnapshot();Assert.Equal(27,w.Transfers.Single().Amount);Assert.Equal(37,w.Tasks.Single().DeadlineAt);Assert.Equal(i,w.Requests.Single().Intent);Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Transfers);}
    [Theory][InlineData(0,37)][InlineData(101,37)][InlineData(27,0)][InlineData(27,3601)] public void InvalidInputsAreRejectedBeforeDispatch(int quantity,int deadline){var w=MissionEntry.Create();Assert.Throws<InvalidDataException>(()=>Plan(w,quantity,deadline));}
    [Theory][InlineData(1)][InlineData(100)] public void QuantityBoundaryIsInclusive(int amount){var s=new WorldSession(MissionEntry.Create());Assert.Equal(ResultCode.Accepted,s.Submit(Plan(s.DiagnosticSnapshot(),amount),s.Revision).Code);s.AdvanceTo(12);Assert.Equal(amount,s.DiagnosticSnapshot().Transfers.Single().Amount);}
    [Fact] public void UnknownExecutorAndWrongPurposeAreRejected(){var w=MissionEntry.Create();Assert.Throws<InvalidDataException>(()=>Plan(w,executor:RegionalBattle.Enemy));Assert.Throws<InvalidDataException>(()=>MissionEntry.Build(w,"request:wrong",ActionKind.Move,ContractFixture.Officer,0,37));}
    [Fact] public void AuthorityIsCheckedWithoutCreatingAnyTask(){var w=MissionEntry.Create();w.Grants=w.Grants.Where(g=>g.Agent!=ContractFixture.Officer||!g.Actions.Contains(ActionKind.Transfer)).ToArray();var s=new WorldSession(w);Assert.Equal(ResultCode.NotAvailable,s.Submit(Plan(w),s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Tasks);}
    [Fact] public void CompletionDeadlineStopsEffectAndReleasesReservation(){var s=new WorldSession(MissionEntry.Create());s.Submit(Plan(s.DiagnosticSnapshot(),deadline:3),s.Revision);s.AdvanceTo(12);var w=s.DiagnosticSnapshot();Assert.Equal(ExecutionPhase.Stopped,w.Tasks.Single().Execution);Assert.Empty(w.Transfers);Assert.DoesNotContain(w.Reservations,r=>r.Phase==ReservationPhase.Active);}
    [Fact] public void InsufficientStockIsNotInvented(){var s=new WorldSession(MissionEntry.Create());s.Submit(Plan(s.DiagnosticSnapshot(),80),s.Revision);s.AdvanceTo(12);var second=Plan(s.DiagnosticSnapshot(),30) with{RequestId=new("request:second")};s.Submit(second,s.Revision);s.AdvanceTo(24);Assert.Single(s.DiagnosticSnapshot().Transfers);Assert.Equal(20,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==ContractFixture.Source).Quantity);}
    [Theory][InlineData(1)][InlineData(2)][InlineData(5)] public void SaveRestoreKeepsChosenIntentAndAppliesOnce(int at){var s=new WorldSession(MissionEntry.Create());s.Submit(Plan(s.DiagnosticSnapshot()),s.Revision);s.AdvanceTo(at);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"entry-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"stage",w.WorldId,new(0,10));var host=new WorldSessionHost(new(MissionEntry.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("stage"),host.Current,host.Current.Revision));host.Current.SetPaused(false);s.AdvanceTo(12);host.Current.AdvanceTo(12);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Requests),ContractJson.Write(host.Current.DiagnosticSnapshot().Requests));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Transfers),ContractJson.Write(host.Current.DiagnosticSnapshot().Transfers));Assert.Equal(ContractJson.Write(s.GetActorView(ContractFixture.Officer).Tasks.Select(t=>t.KnownStatus)),ContractJson.Write(host.Current.GetActorView(ContractFixture.Officer).Tasks.Select(t=>t.KnownStatus)));}
    [Fact] public void OldFixtureAndSaveAreNotSilentlyMigrated(){var old=OfficerLoop.Create();Assert.False(MissionEntry.Enabled(old));Assert.NotEqual(old.Definitions.Version,MissionEntry.Create().Definitions.Version);}
}
